const input = $input.first();
const json = input.json;
let issueKey = '';
let project = '';
let skill = '';
let triggerSource = 'mattermost';

// Phát hiện trigger source
try {
  const trigWebhook = $('Webhook').first();
  if (trigWebhook && trigWebhook.json && trigWebhook.json.headers) {
    triggerSource = 'webhook';
  }
} catch (_) {}

if (json.params) {
  issueKey = json.params.issueKey || '';
  project = json.params.project || '';
  skill = json.params.skill || '';
} else if (json.body) {
  issueKey = json.body.issueKey || '';
  project = json.body.project || '';
  skill = json.body.skill || '';
}

if (!issueKey && json.issueKey) {
  issueKey = json.issueKey;
}

if (!issueKey) {
  return [{
    json: {
      error: 'Thiếu tham số issueKey.',
      issueKey: '',
      project: project,
      skill: skill,
      _triggerSource: triggerSource
    }
  }];
}

return [{
  json: {
    issueKey: issueKey.toUpperCase(),
    project: (project || '').trim(),
    skill: (skill || 'run-test').trim(),
    _triggerSource: triggerSource
  }
}];

const { exec } = require('child_process');
const util = require('util');
const fs = require('fs');
const path = require('path');
const execAsync = util.promisify(exec);

const extractNode = $('Extract issueKey').first()?.json || {};
const issueKey = (extractNode.issueKey || '').toUpperCase();
let project = (extractNode.project || '').trim();
const triggerSource = extractNode._triggerSource || 'mattermost';

if (extractNode.error || !issueKey) {
  return [{
    json: {
      stdout: '',
      stderr: extractNode.error || 'Thiếu tham số issueKey.',
      exitCode: 1,
      error: { message: extractNode.error || 'Thiếu tham số issueKey.' },
      project: project,
      issueKey: issueKey,
      _triggerSource: triggerSource
    }
  }];
}

let cwd = ($env && $env.AGENT_WORKSPACE_DIR) || process.cwd();

// Đọc danh sách project mapping từ projects.json
let projects = {};
try {
  const projectsFile = path.resolve(cwd, 'projects.json');
  if (fs.existsSync(projectsFile)) {
    projects = JSON.parse(fs.readFileSync(projectsFile, 'utf8'));
  }
} catch (e) {}

// Phân giải thư mục gốc theo project
if (project) {
  if (projects[project]) {
    cwd = projects[project];
  } else {
    const scanDirsRaw = ($env && $env.PROJECT_SCAN_DIRS) || process.env.PROJECT_SCAN_DIRS || '';
    const scanDirs = scanDirsRaw.split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
    let foundDir = '';
    for (const sDir of scanDirs) {
      const candidate = path.resolve(sDir, project);
      if (fs.existsSync(candidate)) { foundDir = candidate; break; }
    }
    if (foundDir) cwd = foundDir;
    else if (fs.existsSync(path.resolve(cwd, project))) cwd = path.resolve(cwd, project);
  }
} else {
  const projectKeys = Object.keys(projects);
  if (projectKeys.length === 1) {
    cwd = projects[projectKeys[0]];
    project = projectKeys[0];
  } else {
    const currentTestDir = path.resolve(cwd, 'workspace', issueKey, 'test');
    if (!fs.existsSync(currentTestDir)) {
      for (const [pName, pPath] of Object.entries(projects)) {
        if (fs.existsSync(path.resolve(pPath, 'workspace', issueKey))) {
          cwd = pPath;
          project = pName;
          break;
        }
      }
    }
  }
}

function isTestFile(filename) {
  if (!filename.toLowerCase().endsWith('.py')) return false;
  const baseName = filename.slice(0, -3).toLowerCase();
  return baseName.startsWith('test') || baseName.endsWith('test');
}

const ticketDir = path.resolve(cwd, 'workspace', issueKey);
const stepsDir = path.resolve(ticketDir, 'test', 'steps');
const testDir = path.resolve(ticketDir, 'test');
const resultDir = path.resolve(ticketDir, 'test', 'result');

// Đảm bảo result dir tồn tại
try {
  if (!fs.existsSync(resultDir)) {
    fs.mkdirSync(resultDir, { recursive: true });
  }
} catch (e) {}

let matchedFiles = [];
let targetDir = '';

if (fs.existsSync(stepsDir)) {
  try {
    const files = fs.readdirSync(stepsDir);
    matchedFiles = files.filter(isTestFile).map(f => path.join('workspace', issueKey, 'test', 'steps', f));
    if (matchedFiles.length > 0) targetDir = 'workspace/' + issueKey + '/test/steps';
  } catch (e) {}
}

if (matchedFiles.length === 0 && fs.existsSync(testDir)) {
  try {
    const files = fs.readdirSync(testDir);
    matchedFiles = files.filter(isTestFile).map(f => path.join('workspace', issueKey, 'test', f));
    if (matchedFiles.length > 0) targetDir = 'workspace/' + issueKey + '/test';
  } catch (e) {}
}

if (matchedFiles.length === 0) {
  let detailMsg = '';
  if (!fs.existsSync(ticketDir)) {
    detailMsg = 'Thư mục ticket workspace/' + issueKey + ' chưa tồn tại trong dự án ' + cwd;
  } else if (!fs.existsSync(testDir)) {
    const existingDirs = fs.readdirSync(ticketDir).filter(f => {
      try { return fs.statSync(path.join(ticketDir, f)).isDirectory(); } catch(e) { return false; }
    });
    detailMsg = 'Ticket ' + issueKey + ' chưa có thư mục `test/` (hiện có: ' + (existingDirs.length > 0 ? existingDirs.join(', ') : 'trống') + '). Cần chạy `qa-auto-design` trước.';
  } else {
    detailMsg = 'Thư mục `workspace/' + issueKey + '/test` đã tồn tại nhưng không tìm thấy file test nào.';
  }
  return [{
    json: {
      stdout: '', stderr: detailMsg, exitCode: 4,
      error: { message: detailMsg }, project, issueKey, targetDir,
      resultDir: path.relative(cwd, resultDir),
      _triggerSource: triggerSource
    }
  }];
}

// Paths cho junit + log output
const junitPath = path.resolve(resultDir, 'junit.xml');
const logPath = path.resolve(resultDir, 'test-output.log');
const quotedFiles = matchedFiles.map(f => '"' + f.replace(/"/g, '\\"') + '"').join(' ');

// Check pytest-html availability
let htmlFlag = '';
try {
  await execAsync('python3 -c "import pytest_html"', { timeout: 5000 });
  const htmlPath = path.resolve(resultDir, 'report.html');
  htmlFlag = ` --html="${htmlPath}" --self-contained-html`;
} catch (_) {}

const command = [
  'pytest', quotedFiles,
  '-o python_files="test*.py *test.py test-*.py *-test.py test_*.py *_test.py"',
  '-s -v -rA --tb=short',
  '-o log_cli=true -o log_cli_level=INFO',
  `--junitxml="${junitPath}"`,
  htmlFlag,
  `2>&1 | tee "${logPath}"`
].filter(Boolean).join(' ');

try {
  const result = await execAsync(command, { encoding: 'utf-8', cwd: cwd, timeout: 300000, shell: '/bin/bash' });
  return [{
    json: {
      stdout: result.stdout || '',
      stderr: result.stderr || '',
      exitCode: 0,
      project, issueKey, targetDir,
      resultDir: path.relative(cwd, resultDir),
      junitPath, logPath,
      _triggerSource: triggerSource
    }
  }];
} catch (err) {
  return [{
    json: {
      stdout: err.stdout || '',
      stderr: err.stderr || err.message,
      exitCode: err.code !== undefined ? err.code : (err.status || 1),
      error: { message: err.message },
      project, issueKey, targetDir,
      resultDir: path.relative(cwd, resultDir),
      junitPath, logPath,
      _triggerSource: triggerSource
    }
  }];
}

const fs = require('fs');
const path = require('path');

const input = $input.first();
const extractNode = $('Extract issueKey').first().json;
const issueKey = extractNode.issueKey || input.json.issueKey || '';
const project = extractNode.project || input.json.project || '';
const triggerSource = extractNode._triggerSource || input.json._triggerSource || 'mattermost';
const targetLabel = project ? (project + ' / ' + issueKey) : issueKey;

// Xử lý lỗi Extract
if (!issueKey || extractNode.error) {
  return [{
    json: {
      success: false,
      reportText: '🚨 **[QA Automation Lỗi]** Không tìm thấy issueKey hợp lệ.\n> Cú pháp: `/agent [project] run-test <issueKey>`',
      _triggerSource: triggerSource
    }
  }];
}

const execRes = input.json;
let success = true;
let outputText = execRes.stdout || '';
let errText = execRes.stderr || '';

if (execRes.error || (execRes.exitCode !== undefined && execRes.exitCode !== 0)) {
  success = false;
}

// Trích xuất stats từ pytest output
const passMatch = outputText.match(/(\d+) passed/);
const failMatch = outputText.match(/(\d+) failed/);
const skipMatch = outputText.match(/(\d+) skipped/);
const errorMatch = outputText.match(/(\d+) error/);
const durationMatch = outputText.match(/in ([\d.]+)s/);

const passedCount = passMatch ? parseInt(passMatch[1]) : 0;
const failedCount = failMatch ? parseInt(failMatch[1]) : 0;
const skippedCount = skipMatch ? parseInt(skipMatch[1]) : 0;
const errorCount = errorMatch ? parseInt(errorMatch[1]) : 0;
const duration = durationMatch ? durationMatch[1] + 's' : 'N/A';

// Rút gọn log output
let logSnippet = (outputText + '\n' + errText).trim();
if (logSnippet.length > 3000) {
  logSnippet = '...(truncated)...\n' + logSnippet.substring(logSnippet.length - 2500);
}

const statusIcon = success ? '✅' : '❌';
const statusText = success ? 'Thành công (Passed)' : 'Thất bại (Failed)';

// Build report content cho file report.md
const now = new Date();
const dateStr = now.toISOString().replace('T', ' ').split('.')[0] + ' ICT';

const failedTests = [];
const failRegex = /FAILED (.+?) - (.+)/g;
let failMatch2;
while ((failMatch2 = failRegex.exec(outputText)) !== null) {
  failedTests.push(`- \`${failMatch2[1]}\`: ${failMatch2[2]}`);
}

const reportMdLines = [
  `# Báo Cáo Kiểm Thử Tự Động — ${issueKey}`,
  ``,
  `- **Thời gian chạy:** ${dateStr}`,
  `- **Ticket:** ${issueKey}${project ? ' (Project: `' + project + '`)' : ''}`,
  `- **Trạng thái tổng thể:** ${statusIcon} **${statusText}**`,
  ``,
  `## 📊 Thống Kê Kết Quả`,
  ``,
  `| Metric | Kết Quả |`,
  `| :--- | :---: |`,
  `| ✅ Passed | **${passedCount}** |`,
  `| ❌ Failed | **${failedCount}** |`,
  `| ⏭️ Skipped | **${skippedCount}** |`,
  `| ⚠️ Errors | **${errorCount}** |`,
  `| ⏱️ Duration | **${duration}** |`,
  ``
];

if (failedTests.length > 0) {
  reportMdLines.push(`## ❌ Test Cases Thất Bại\n`);
  reportMdLines.push(failedTests.join('\n'));
  reportMdLines.push('');
}

reportMdLines.push(`## 📄 Full Log Output`, ``, '```text', logSnippet, '```', '');

if (failedCount > 0 || errorCount > 0) {
  reportMdLines.push(
    `## 💡 Đề Xuất Hành Động Tiếp Theo`, ``,
    `- 🛠️ **Gỡ lỗi nguyên nhân gốc rễ:** Chạy skill \`dev-debugging\``,
    `- 🔍 **Review code chất lượng:** Chạy skill \`cr-review-code-and-quality\``,
    `- ⚙️ **Cập nhật test script:** Chạy skill \`qa-auto-design\``
  );
}

const reportMdContent = reportMdLines.join('\n');

// Ghi file report.md
let reportPath = '';
try {
  const cwdBase = ($env && $env.AGENT_WORKSPACE_DIR) || process.cwd();
  const resultDir = path.resolve(cwdBase, 'workspace', issueKey, 'test', 'result');
  if (!fs.existsSync(resultDir)) fs.mkdirSync(resultDir, { recursive: true });
  reportPath = path.join(resultDir, 'report.md');
  fs.writeFileSync(reportPath, reportMdContent, 'utf-8');
} catch (e) {}

const reportDirStr = `workspace/${issueKey}/test/result/`;

const mattermostMsg = [
  `🚀 **[QA Automation]** Kết quả kiểm thử ticket **${targetLabel}**:`,
  `- Trạng thái: ${statusIcon} **${statusText}** | Passed: **${passedCount}** | Failed: **${failedCount}** | Time: **${duration}**`,
  reportPath ? `- Báo cáo đầy đủ: \`${reportDirStr}report.md\`` : '',
  execRes.junitPath ? `- JUnit XML: \`${reportDirStr}junit.xml\`` : '',
  ``,
  '```text',
  logSnippet.length > 1500 ? logSnippet.substring(logSnippet.length - 1500) : logSnippet,
  '```',
  failedCount > 0 ? `\n💡 *Gợi ý: Chạy \`dev-debugging\` hoặc \`cr-review-code-and-quality\` để điều tra lỗi.*` : ''
].filter(Boolean).join('\n');

return [{ json: { success, reportText: mattermostMsg, issueKey, project, _triggerSource: triggerSource } }];
